BEGIN;
CREATE TEMP TABLE jobs(job_id TEXT PRIMARY KEY, status TEXT NOT NULL, error TEXT, cancel_requested BOOLEAN NOT NULL DEFAULT FALSE, acceleration_report TEXT, updated_at TEXT NOT NULL) ON COMMIT DROP;
PREPARE r(text,text,text,text,text) AS
WITH v(id, msg) AS (VALUES ($1, $2))
UPDATE jobs
   SET status = 'failed', error = v.msg, acceleration_report = CASE WHEN acceleration_report = $3 THEN $4 ELSE acceleration_report END,
       updated_at = $5
  FROM v
 WHERE jobs.job_id = v.id AND jobs.status = 'queued'
RETURNING jobs.job_id;
\echo === RETURNING k=1 failed ===
EXECUTE r('d0000','dependency `a` failed for job `d0000`','{"state":"pending"}','{"state":"undetermined","reason":"dependency_failed"}','2026-09-10T00:00:00Z');
\echo === state ===
SELECT status, cancel_requested, coalesce(acceleration_report,'<NULL>') ar, updated_at, count(*) FROM jobs GROUP BY 1,2,3,4 ORDER BY 1,3;
SELECT 'updated_at_nulls', count(*) FROM jobs WHERE updated_at IS NULL;
ROLLBACK;
BEGIN;
CREATE TEMP TABLE jobs(job_id TEXT PRIMARY KEY, status TEXT NOT NULL, error TEXT, cancel_requested BOOLEAN NOT NULL DEFAULT FALSE, acceleration_report TEXT, updated_at TEXT NOT NULL) ON COMMIT DROP;
PREPARE r(text,text,text,text,text) AS
WITH v(id, msg) AS (VALUES ($1, $2))
UPDATE jobs
   SET status = 'cancelled', error = v.msg, cancel_requested = TRUE,
       acceleration_report = CASE WHEN acceleration_report = $3 THEN $4 ELSE acceleration_report END,
       updated_at = $5
  FROM v
 WHERE jobs.job_id = v.id AND jobs.status = 'queued'
RETURNING jobs.job_id;
\echo === RETURNING k=1 cancelled ===
EXECUTE r('d0000','dependency `a` failed for job `d0000`','{"state":"pending"}','{"state":"undetermined","reason":"cancelled"}','2026-09-10T00:00:00Z');
